import nucleux from "@nucleux/tokens/preset";

/** @type {import('tailwindcss').Config} */
export default {
  presets: [nucleux],
  content: [
    "./index.html",
    "./src/**/*.{js,ts,jsx,tsx}",
    // Required: Nucleux components ship Tailwind classes that your build must generate.
    "./node_modules/@nucleux/*/dist/**/*.{js,cjs}",
  ],
};

props.source:
export interface AccordionProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** Allow multiple panels open at once. */
  type?: "single" | "multiple";
  /** Initial open value(s). */
  defaultValue?: string | string[];
}

export interface AccordionItemProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Unique key identifying the panel controlled by this item. */
  value: string;
}

export interface AccordionTriggerProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Additional classes merged onto the full-width trigger row. */
  className?: string;
}

export interface AccordionContentProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the collapsible panel body. */
  className?: string;
}

export interface AgentAvatarProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** The agent's name ("Aria"). Part of the accessible name: "Aria, AI agent". */
  name: string;
  /** An approved, non-photographic mark image. Never a photo or a human face. */
  src?: string;
  /** What to draw inside the mark when there is no `src`: the reserved AI sparkle by default, or a letter ("A"). */
  glyph?: React.ReactNode;
  /** 24 / 32 / 40 px — the same drawing at every size. */
  size?: AgentAvatarSize;
  /** `circle` (default) or `rounded` square — use `rounded` when people in the same list are circles. */
  shape?: AgentAvatarShape;
  /**
   * The agent is working (the `animated-mark` variant): the working ring
   * pulses on the mark itself and stops the moment work stops. Still under
   * reduced motion; the words carry it.
   */
  working?: boolean;
  /**
   * Live state shown as a dot on the mark (the `status-aware` variant):
   * `online`, `offline` or `working`. The dot never travels alone — its
   * words are announced in a polite live region (see `statusLabel`).
   */
  status?: AgentAvatarStatus;
  /** Words for the state ("Online · ready", "Generating…"). Defaults to Online / Offline / Working. */
  statusLabel?: string;
  /** What kind of thing this is, appended to the name: "AI agent" by default. */
  descriptor?: string;
  /** Hide the mark from assistive tech when the name is already written beside it (e.g. in an AgentName lockup). */
  decorative?: boolean;
}

export interface AiWorkingIconProps extends AiGlyphProps {
  /** Hold the mark still (it only turns while work is happening). */
  still?: boolean;
}

export interface AiIconProviderProps {
  /** Product-wide choice of approved glyph per role. Set once; unset roles keep the default. */
  glyphs?: AiIconGlyphs;
  children?: React.ReactNode;
}

export interface AiIconProps extends Omit<React.HTMLAttributes<HTMLSpanElement>, "role"> {
  /**
   * Which AI meaning this is: `ai-action` (a control runs AI),
   * `generated-content` (AI wrote this), `agent-working` (the agent is
   * working now — announced politely) or `tool-use` (the agent used a tool).
   */
  role: AiIconRole;
  /** The words that travel with the mark ("Rewrite", "Generated with AI", "Rewriting release note…"). Required: a mark is never alone. */
  label: React.ReactNode;
  /** Show the words visibly (default) or keep them for assistive tech only. */
  showLabel?: boolean;
}

export interface AiIconsProps extends React.HTMLAttributes<HTMLSpanElement> {
  /**
   * `sparkle` (the universal "AI" mark in a tile), `thinking-orb` (an
   * animated orb for active, listening or generating states) or
   * `branded-mark` (your product's own shape or letter).
   */
  variant?: AiIconsVariant;
  /** 24 / 32 / 40 px. */
  size?: AiIconsSize;
  /** `solid` (filled tile) or `outline` (bordered tile). Sparkle and branded mark only. */
  tone?: AiIconsTone;
  /** Accessible name. Omit when words sit beside the mark — it is then decorative. */
  label?: string;
  /** Content of the branded mark (a letter or your SVG). Defaults to the first letter of `label`, else the sparkle. */
  glyph?: React.ReactNode;
}

export interface AlertProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** Visual style: "info" (neutral, default), "success", "warning", or "destructive". */
  variant?: AlertVariant;
  /**
   * Alias of `variant` (MUI Alert vocabulary). Deprecated — use `variant`.
   * @deprecated Use `variant` instead. Alias kept so MUI-trained agents and
   *   users are caught; it maps 1:1 ("error" -> "destructive").
   */
  severity?: AlertVariant | "error";
  /** Optional bold title above the body. */
  title?: React.ReactNode;
  /** Custom icon; defaults to a variant-appropriate one. */
  icon?: React.ReactNode;
  /** Hide the leading icon entirely. */
  hideIcon?: boolean;
}

export interface AlertDialogProps {
  /** Whether the alert dialog is open. */
  open: boolean;
  /** Called when the dialog requests to close (Escape / a button). */
  onOpenChange: (open: boolean) => void;
  title: React.ReactNode;
  description?: React.ReactNode;
  /** Confirm button label. */
  confirmLabel?: string;
  /** Cancel button label. */
  cancelLabel?: string;
  onConfirm?: () => void;
  onCancel?: () => void;
  /** Style the confirm action as destructive. */
  destructive?: boolean;
  /** Extra content between the description and the actions. */
  children?: React.ReactNode;
  className?: string;
}

export interface AspectRatioProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Width / height ratio (e.g. 16/9). Defaults to 1 (square). */
  ratio?: number;
}

export interface AttachmentProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** File or attachment name. */
  name: React.ReactNode;
  /** Metadata line, e.g. `"PDF · 240 KB"`. */
  meta?: React.ReactNode;
  /** Image URL — renders a thumbnail tile instead of a document chip. */
  thumbnail?: string;
  /** Doctype icon for the document chip. Defaults to a document glyph. */
  icon?: React.ReactNode;
  /** Called when the remove control is used. Hidden if omitted. */
  onRemove?: () => void;
}

export interface AttachmentGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the tray. */
  className?: string;
}

export interface AttachmentsProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onError"> {
  /** The attached files and their states (the app owns uploading and reading). */
  items?: AttachmentsFile[];
  /** Tray layout. Defaults to `"file-chip"`. */
  variant?: AttachmentsVariant;
  /** Called with files that passed the limits; start uploading them here. */
  onFilesAdded?: (files: File[]) => void;
  /** Called with files refused before upload (wrong type, too big, too many). */
  onFilesRejected?: (rejections: AttachmentsRejection[]) => void;
  /** Called when a file's remove control is used. */
  onRemove?: (id: string) => void;
  /** Called from a failed file's Retry. */
  onRetry?: (id: string) => void;
  /** Accepted types, as for `<input accept>`: `".pdf,.csv,image/*"`. */
  accept?: string;
  /** Most files allowed at once, counting those already attached. */
  maxFiles?: number;
  /** Largest file allowed, in bytes. */
  maxSize?: number;
  /** Turns off adding (the tray still shows and removes). */
  disabled?: boolean;
  /** Accessible name of the region. Defaults to `"Attached to this message"`. */
  label?: string;
}

export interface AttachmentsItemProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onError"> {
  /** The file to show. */
  file: AttachmentsFile;
  /** Layout; defaults to the parent's `variant`, else `"file-chip"`. */
  variant?: AttachmentsVariant;
  /** Remove handler; defaults to the parent's `onRemove`. */
  onRemove?: (id: string) => void;
  /** Retry handler for a failed file; defaults to the parent's `onRetry`. */
  onRetry?: (id: string) => void;
}

export interface AttachmentsTrayProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Items to show; defaults to the parent's `items`. */
  items?: AttachmentsFile[];
}

export interface AttachmentsDropZoneProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** Force the lit "drop to attach" state (it lights up on its own while a file is dragged over). */
  active?: boolean;
  /** Headline while dragging. Defaults to `"Drop to attach"`. */
  title?: React.ReactNode;
  /** Line under the headline, e.g. `"PDF, image, CSV, doc"`. Defaults to the limits in words. */
  description?: React.ReactNode;
  /** Label of the browse button in the idle box. Defaults to `"Choose files"`. */
  browseLabel?: React.ReactNode;
}

export interface AutocompleteProps
  extends Omit<TextareaProps, "value" | "defaultValue" | "onChange" | "className"> {
  /** Field value (controlled). */
  value?: string;
  /** Initial value (uncontrolled). */
  defaultValue?: string;
  /** Called with the new text on every edit and on accept. */
  onValueChange?: (value: string) => void;
  /** Native change handler, still called on typing. */
  onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;
  /**
   * Supplies the completion for the text so far — the app calls its model here.
   * Return the continuation to show after the caret (a result that repeats the
   * typed text is trimmed to the part after it), or `null` for none. May be async.
   */
  getSuggestion?: (
    text: string,
    request: AutocompleteRequest,
  ) => string | null | undefined | Promise<string | null | undefined>;
  /** A fixed suggestion to show (controlled), instead of calling `getSuggestion`. */
  suggestion?: string | null;
  /** Layout of the suggestion. Defaults to `"ghost-suffix"`. */
  variant?: AutocompleteVariant;
  /** Characters needed before asking for a suggestion. Defaults to `8`. */
  minChars?: number;
  /** Wait after the last keystroke before asking, in ms. Defaults to `150`. */
  debounceMs?: number;
  /** Key that accepts the whole suggestion. Defaults to `"tab"`. ⌘/Ctrl + → always accepts one word. */
  acceptKey?: AutocompleteAcceptKey;
  /** Called with the text that was inserted when a suggestion (or a word of it) is accepted. */
  onAccept?: (inserted: string) => void;
  /** Called when Escape dismisses the suggestion. It stays away until the field is cleared. */
  onDismiss?: () => void;
  /** Called when `getSuggestion` throws or rejects. The field keeps working without a suggestion. */
  onError?: (error: unknown) => void;
  /** Called whenever the completion state changes. */
  onStateChange?: (state: AutocompleteState) => void;
  /** Visible label for the field. Without it, pass `aria-label`. */
  label?: React.ReactNode;
  /** Classes for the outer wrapper. */
  className?: string;
  /** Classes for the text field itself. */
  fieldClassName?: string;
  /** Hide the "Tab to accept / Esc to dismiss" row of the sentence and block variants. */
  hideHints?: boolean;
}

export interface AvatarProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Role used to pick a default icon and styling when no image/initials given. */
  role?: MessageRole;
  /** Optional image URL; takes precedence over initials and the role icon. */
  src?: string;
  /** Explicit initials. If omitted, derived from `name`. */
  initials?: string;
  /** Display name — used to derive initials and the default aria-label. */
  name?: string;
  /** Corner style. `rounded` suits entity/person avatars, `circle` suits chat. */
  shape?: "circle" | "rounded";
  /** Accessible label / alt text. */
  alt?: string;
}

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Visual style. */
  variant?: BadgeVariant;
  /** Optional icon rendered before the label. */
  icon?: React.ReactNode;
}

/** Breadcrumb navigation landmark. Compose with the parts below. */
export interface BreadcrumbProps extends React.HTMLAttributes<HTMLElement> {
  /** Additional classes merged onto the outer nav wrapper. */
  className?: string;
}

export interface BreadcrumbItemProps extends React.LiHTMLAttributes<HTMLLIElement> {
  /** Additional classes merged onto the crumb list item. */
  className?: string;
}

export interface BreadcrumbLinkProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  /** Additional classes merged onto the crumb anchor. */
  className?: string;
}

/** The current page — non-interactive, marked with aria-current. */
export interface BreadcrumbPageProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Additional classes merged onto the current-page crumb. */
  className?: string;
}

export interface BreadcrumbSeparatorProps extends React.LiHTMLAttributes<HTMLLIElement> {
  /** Additional classes merged onto the separator glyph container. */
  className?: string;
  /** Custom separator glyph; defaults to a ChevronRight icon. */
  children?: React.ReactNode;
}

export interface BubbleProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Fill of the BubbleContent: "default" (primary), "secondary", "muted",
   * "tinted" (light primary), "outline", "ghost" (no chrome, full width) or
   * "destructive" (an error message).
   */
  variant?: BubbleVariant;
  /** "start" (default, incoming) or "end" (outgoing: pushed to the trailing side). */
  align?: BubbleAlign;
}

export interface BubbleContentProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Render the single child (e.g. a `<button>` or `<a>`) as the bubble surface, making it interactive. */
  asChild?: boolean;
}

export interface BubbleReactionsProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Corner to pin to horizontally: "start" or "end" (default). */
  align?: BubbleAlign;
  /** Edge to overlap: "top" or "bottom" (default). */
  side?: BubbleReactionsSide;
}

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Visual style: "primary" (default), "cta", "secondary", "ghost", "destructive", or "link". */
  variant?: ButtonVariant;
  /**
   * Alias of `variant` (MUI/Chakra vocabulary). Deprecated — use `variant`.
   * @deprecated Use `variant` instead. Alias kept so MUI/Chakra-trained
   *   agents and users are caught; it maps 1:1.
   */
  color?: ButtonVariant;
  /**
   * Size preset: "sm", "md" (default), "lg", or a square icon-only size
   * ("icon-sm", "icon", "icon-lg"). Icon-only buttons need an `aria-label`.
   */
  size?: ButtonSize;
  /**
   * Render the single child element (e.g. an `<a>` or a router `Link`) with
   * the button's styles instead of a `<button>`. `leftIcon`/`rightIcon` are
   * ignored; put icons inside the child.
   */
  asChild?: boolean;
  /** Icon rendered before the label. */
  leftIcon?: React.ReactNode;
  /** Icon rendered after the label. */
  rightIcon?: React.ReactNode;
}

export interface ButtonGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Lay the children out in a row ("horizontal", default) or a column ("vertical"). */
  orientation?: ButtonGroupOrientation;
}

export interface ButtonGroupTextProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Render the single child (e.g. a `<Label>` or `<span>`) with the text block's styles. */
  asChild?: boolean;
}

/** Card header. Lays children out in a row with space-between by default. */
export interface CardHeaderProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the card header row. */
  className?: string;
}

export interface CardTitleProps extends React.HTMLAttributes<HTMLHeadingElement> {
  /** Additional classes merged onto the card title. */
  className?: string;
}

export interface CardDescriptionProps extends React.HTMLAttributes<HTMLParagraphElement> {
  /** Additional classes merged onto the card description. */
  className?: string;
}

/** Trailing action in a card header, e.g. a "View all" link. Renders a button by default. */
export interface CardActionProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Additional classes merged onto the header action button. */
  className?: string;
  /** Button type. Defaults to "button". */
  type?: "button" | "submit" | "reset";
}

export interface CardContentProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the card body. */
  className?: string;
}

/** Full-bleed hairline divider between card sections. */
export interface CardDividerProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional classes merged onto the divider. */
  className?: string;
}

export interface CarouselProps extends React.HTMLAttributes<HTMLDivElement> {
  orientation?: Orientation;
  opts?: EmblaOptionsType;
  /** Receive the Embla API instance once ready. */
  setApi?: (api: EmblaCarouselType | undefined) => void;
}

export interface CaveatProps extends React.HTMLAttributes<HTMLParagraphElement> {
  /** Placement style. Default `below-input`. */
  variant?: CaveatVariant;
  /** Leading icon. Defaults to an info glyph. Pass `null` to omit. */
  icon?: React.ReactNode;
  /**
   * Next steps that remove the reason for the caveat — "Review sources",
   * "Reconnect". Shown after the text; use small Buttons or links.
   */
  actions?: React.ReactNode;
}

export interface CaveatTooltipProps extends Omit<React.HTMLAttributes<HTMLSpanElement>, "content"> {
  /** The caveat. Default "Output may be inaccurate". */
  content?: React.ReactNode;
  /** Side of the trigger. Default `top`. */
  side?: TooltipSide;
  /** Show the info glyph in the tooltip. Default `true`. */
  showIcon?: boolean;
  /** The AI action the caveat rides on — a single focusable element (e.g. an `Iconography` or Button). */
  children: React.ReactElement;
}

export interface ChartContainerProps extends React.HTMLAttributes<HTMLDivElement> {
  config: ChartConfig;
  /** A single recharts chart element (BarChart, LineChart, …). */
  children: React.ReactElement;
}

export interface ChartTooltipContentProps {
  active?: boolean;
  payload?: TooltipPayloadItem[];
  label?: React.ReactNode;
  config?: ChartConfig;
}

export interface ChartLegendContentProps {
  payload?: LegendPayloadItem[];
  config?: ChartConfig;
}

export interface CheckboxProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange" | "value" | "type"> {
  /** Controlled checked state. */
  checked?: boolean;
  /** Initial state when uncontrolled. */
  defaultChecked?: boolean;
  /** Called with the next checked state. */
  onCheckedChange?: (checked: boolean) => void;
}

export interface CodeBlockProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The raw source code to display. */
  code: string;
  /** Language label shown in the header (e.g. "ts", "python"). */
  language?: string;
  /** Hide the copy button. */
  hideCopy?: boolean;
}

export interface CollapsibleProps extends React.HTMLAttributes<HTMLDivElement> {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  disabled?: boolean;
}

export interface CollapsibleTriggerProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Hide the default chevron affordance. */
  hideChevron?: boolean;
}

export interface AiColorProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Treatment: `accent-border` (a coloured edge on streaming / AI-touched
   * copy), `soft-glow` (a halo around an active AI region) or
   * `background-tint` (a faint fill behind a whole AI-generated region).
   */
  variant?: AiColorVariant;
  /**
   * The AI is working in this region right now: adds the working treatment
   * (a pulsing accent ring, plus a streaming caret on `accent-border`) and
   * sets `aria-busy`. Holds still under reduced motion.
   */
  working?: boolean;
  /**
   * The words that travel with the colour — "Streaming", "Aria suggests".
   * Rendered in a polite live region so a change (e.g. "Streaming" →
   * "Done") is announced. Colour is never the only signal.
   */
  label?: React.ReactNode;
  /** Apply the treatment to the single child element instead of a wrapper `<div>`. */
  asChild?: boolean;
}

export interface AiColorDotProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Pulse while the agent is working (holds still under reduced motion). */
  pulse?: boolean;
}

export interface ComboboxProps {
  options: ComboboxOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  searchPlaceholder?: string;
  emptyText?: string;
  disabled?: boolean;
  className?: string;
  /** Accessible name for the trigger. */
  "aria-label"?: string;
}

export interface CommandGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  heading?: React.ReactNode;
}

export interface CommandItemProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSelect"> {
  /** The value used for filtering + selection. Defaults to the text content. */
  value: string;
  disabled?: boolean;
  onSelect?: (value: string) => void;
}

export interface ConnectorProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** Connector name, e.g. `"GitHub"`. */
  name: React.ReactNode;
  /** What the connector gives the agent access to. */
  description?: React.ReactNode;
  /** Connector logo/icon. Defaults to a plug glyph. */
  icon?: React.ReactNode;
  /** Whether the connector is already connected. Shorthand for `status="connected"`. */
  connected?: boolean;
  /** Full connection state; overrides `connected` when set. */
  status?: ConnectorStatus;
  /** Called to connect. Renders the connect button when set and not connected. */
  onConnect?: () => void;
  /** Called to disconnect. Renders a manage/disconnect control when connected. */
  onDisconnect?: () => void;
  /** Called to sign in again when `status` is `"expired"` or `"error"`. Falls back to `onConnect`. */
  onReconnect?: () => void;
  /** Label for the connect action. Defaults to a localized "Connect". */
  connectLabel?: React.ReactNode;
  /** Label for the disconnect action. Defaults to a localized "Disconnect". */
  disconnectLabel?: React.ReactNode;
  /** What the agent will be able to do, in plain verbs — shown before the handoff, e.g. `["Read files in folders you choose", "Search file names"]`. */
  scopes?: React.ReactNode[];
  /** Who the sign-in is with, e.g. `"sam@acme.com"`. Shown once connected. */
  account?: React.ReactNode;
  /** What went wrong, when `status` is `"error"`. */
  error?: React.ReactNode;
}

export interface ConnectorListProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Accessible name. Defaults to `"Connected services"`. */
  label?: string;
}

export interface ConnectorScopePickerProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title" | "defaultValue" | "onChange"> {
  /** The scopes on offer. */
  scopes: ConnectorScope[];
  /** Granted scope ids (controlled). */
  value?: string[];
  /** Initial grant (uncontrolled). Defaults to none — least privilege. */
  defaultValue?: string[];
  /** Called with the granted ids. */
  onValueChange?: (ids: string[]) => void;
  /** Who reads. Defaults to `"Aria"`. */
  agentName?: React.ReactNode;
  /** Heading override. Defaults to `"<agent> can read from:"`. */
  title?: React.ReactNode;
  /** Write access, asked separately (controlled). Renders the write switch when this or `onAllowWriteChange` is set. */
  allowWrite?: boolean;
  /** Called when write access is switched. */
  onAllowWriteChange?: (on: boolean) => void;
  /** Label for the write switch. Defaults to `"Also allow changes (create, edit, post)"`. */
  writeLabel?: React.ReactNode;
}

export interface ConnectorLivePillProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** The connector being read, e.g. `"Drive"`. */
  source?: React.ReactNode;
  /** How many items are being read. */
  count?: number;
  /** Noun for `count`. Defaults to `"docs"`. */
  noun?: string;
}

/** The request itself, shared by `Consent` and `ConsentDialog`. */
export interface ConsentRequestProps {
  /** Heading of the consent card. */
  title: React.ReactNode;
  /** The one-line summary: what is asked, why, and what happens next. */
  description?: React.ReactNode;
  /** The permissions the user can grant, each separately. Omit for a single yes/no request. */
  permissions?: ConsentPermission[];
  /** Label for the deny button. */
  denyLabel?: string;
  /** Called when the user denies all permissions. */
  onDeny?: () => void;
  /** Optional middle action, e.g. "Always Allow". */
  secondaryLabel?: string;
  /** Called with the selected permission ids when the secondary action runs. */
  onSecondary?: (selectedIds: string[]) => void;
  /** Label for the allow button. Defaults to "Allow selected" with permissions, "Allow" without. */
  allowLabel?: string;
  /** Called with the ids of the granted permissions. */
  onAllow?: (selectedIds: string[]) => void;
  /** Link to the full policy. The spec requires one wherever consent is asked. */
  policyHref?: string;
  /** Text of the policy link. Default "Read our privacy policy". */
  policyLabel?: React.ReactNode;
}

export interface ConsentProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title">,
    ConsentRequestProps {}

export interface ConsentDialogProps extends ConsentRequestProps {
  /** Whether the dialog is open. */
  open: boolean;
  /** Called with `false` after the person answers (the dialog cannot be dismissed without an answer). */
  onOpenChange: (open: boolean) => void;
  /** Class overrides for the dialog panel. */
  className?: string;
}

export interface ConsentToggleProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title" | "onChange" | "defaultChecked"> {
  /** What the setting allows ("Help improve Aria with my data"). The switch's accessible name. */
  title: React.ReactNode;
  /** Supporting line ("Anonymised. Opt out anytime."). The switch's description. */
  description?: React.ReactNode;
  /** Controlled state. */
  checked?: boolean;
  /** Initial state when uncontrolled. Default off. */
  defaultChecked?: boolean;
  /** Called with the new state. */
  onCheckedChange?: (checked: boolean) => void;
  /** Disable the switch. */
  disabled?: boolean;
}

export interface ContextMenuProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "content"> {
  /** Menu items — compose ContextMenuItem / ContextMenuSeparator / ContextMenuLabel. */
  content: React.ReactNode;
  /** The area that opens the menu on right-click. */
  children: React.ReactNode;
}

export interface ContextMenuItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  icon?: React.ReactNode;
  trailing?: React.ReactNode;
  destructive?: boolean;
}

export interface DataTableProps<TData, TValue> {
  columns: ColumnDef<TData, TValue>[];
