  onFilesChange?: (files: VisualInputFile[]) => void;
  /** Called with files that were refused (wrong type, too large, too many). */
  onReject?: (rejections: VisualInputRejection[]) => void;
  /** Main line of the drop zone. */
  label?: React.ReactNode;
  /** Secondary line, e.g. `"PNG, JPG, PDF · up to 20 MB"`. Derived from `accept`/`maxSize` when omitted. */
  hint?: React.ReactNode;
  /** Accessible name of the whole region. Defaults to `"Image input"`. */
  regionLabel?: string;
  /** Line shown once something is attached, e.g. `"Aria will see this when you send"`. */
  seeText?: React.ReactNode;
  /** Explains camera access before anything is captured (camera variant). */
  cameraText?: React.ReactNode;
  /** Says what can be used when a type is refused, e.g. `"Aria can read PNG, JPG and HEIC."`. */
  unsupportedText?: string;
  /** Label of the browse button. */
  browseLabel?: string;
  /** Label of the camera button. */
  cameraLabel?: string;
  /** Disable every source. */
  disabled?: boolean;
  /** Slot rendered under the previews — typically the composer the visual is paired with. */
  children?: React.ReactNode;
}

export interface VoiceInputProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Presentation. Defaults to `"waveform"`. */
  variant?: VoiceInputVariant;
  /** Current state of the dictation flow. */
  state?: VoiceInputState;
  /** Elapsed time label while recording, e.g. `"0:12"`. */
  duration?: React.ReactNode;
  /** Transcribed text: the final words (shown while recording in `"transcript-stream"`, and once transcribing). */
  transcript?: React.ReactNode;
  /** Words still being heard (not final) — shown muted after `transcript`, with a caret. */
  interimTranscript?: React.ReactNode;
  /** Called from the idle mic button to start recording. */
  onStart?: () => void;
  /** Called to cancel/discard the recording. Typed text is untouched. */
  onCancel?: () => void;
  /** Called to stop recording and confirm. The transcript goes to the field for review — it never sends. */
  onConfirm?: () => void;
  /** Called to pause capture (mic off, progress kept). Renders a Pause control while recording. */
  onPause?: () => void;
  /** Called to resume a paused recording. */
  onResume?: () => void;
  /** Called from the error state to try again. */
  onRetry?: () => void;
  /** Label shown while idle. Defaults to `"Tap to speak"`. */
  idleLabel?: React.ReactNode;
  /** Label shown while capturing, e.g. `"Aria is listening"`. Defaults to `"Listening"`. */
  listeningLabel?: React.ReactNode;
  /** Message shown in the error state. Defaults to `"Couldn’t make out all of that."`. */
  errorText?: React.ReactNode;
}

export interface VoiceToneProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "onSubmit" | "defaultValue"> {
  /** Where the scaffold sits. Defaults to `"settings"`. */
  variant?: VoiceToneVariant;
  /** How tones are chosen. Defaults to `"cards"`. */
  layout?: VoiceToneLayout;
  /** The tones on offer — three or four familiar ones. Defaults to {@link defaultVoiceTones}. Pass `[]` for a rules-only panel. */
  tones?: VoiceToneOption[];
  /** Chosen tone id (controlled). `null` is the agent's default voice; `"custom"` a described tone. */
  value?: string | null;
  /** Initial tone id (uncontrolled). Defaults to `null`. */
  defaultValue?: string | null;
  /** Called when the tone is chosen, switched, removed or restored. */
  onValueChange?: (value: string | null) => void;
  /** Offer “Or describe a tone”. Defaults to `true` in the composer and chip, `false` in settings. */
  allowCustom?: boolean;
  /** The described tone (controlled). */
  customTone?: string;
  /** Initial described tone (uncontrolled). */
  defaultCustomTone?: string;
  /** Called when a described tone is applied. */
  onCustomToneChange?: (text: string) => void;
  /** The rules list (settings panel). The composer variants send the rules that are on with each request. */
  rules?: VoiceToneRule[];
  /** Ids of the rules that are on (controlled). */
  ruleValues?: string[];
  /** Ids of the rules that are on initially (uncontrolled). */
  defaultRuleValues?: string[];
  /** Called with the ids of the rules that are on. */
  onRulesChange?: (ids: string[]) => void;
  /** Show the sample sentence for the tone in focus or chosen. Defaults to `true`. */
  showSample?: boolean;
  /** Let people remove the tone from the composer (with Undo). Defaults to `true`. */
  removable?: boolean;
  /** Picker open (controlled), for the composer and chip variants. */
  open?: boolean;
  /** Picker open initially (uncontrolled). */
  defaultOpen?: boolean;
  /** Called when the picker opens or closes. */
  onOpenChange?: (open: boolean) => void;
  /**
   * Seed the quiet line, e.g. to show a state in docs. A seeded `"removed"` line's Undo restores the
   * recommended (or first) tone.
   */
  defaultNotice?: VoiceToneNotice | null;
  /** Name of the setting — the chip, picker and group label. Defaults to `"Tone"`. */
  label?: string;
  /** Who writes, for the notices. Defaults to `"Aria"`. */
  agentName?: string;
  /** Composer text (controlled). The tone never edits it. */
  draft?: string;
  /** Initial composer text (uncontrolled). Cleared after a send. */
  defaultDraft?: string;
  /** Called when the composer text changes. */
  onDraftChange?: (text: string) => void;
  /** Called on send with the trimmed text and the tone setting, sent beside the prompt. */
  onSubmit?: (text: string, setting: VoiceToneSetting) => void;
  /** Composer placeholder, also its accessible name. Defaults to `"Describe what to write…"`. */
  placeholder?: string;
  /** Show the agent as busy — the send button becomes a stop button. */
  loading?: boolean;
  /** Called by the stop button while `loading`. */
  onStop?: () => void;
  /** More composer tools, placed after the Tone chip. */
  actions?: React.ReactNode;
  /** Composer controls placed first in the toolbar, before the Tone chip or Request settings (attach, +…). */
  composerLeading?: React.ReactNode;
  /**
   * "chip" (default): the Tone chip sits in the composer. "settings": no chip; a Request settings
   * control right after `composerLeading` lists Tone (with its value) and opens the tone picker.
   */
  trigger?: VoiceToneTrigger;
  /** With `trigger="settings"`: the app's other request settings for the same menu (Mode, Style, Improve prompt…), merged in the site's order. */
  settingsItems?: RequestSettingsItem[];
  /** With `trigger="settings"`: called when one of `settingsItems` is chosen. */
  onSettingsSelect?: (id: string) => void;
}

